  ('IN-HCBS-AL-2026-MANDATE-SUPERSEDED', 'sairncare_payer_rules_seed.json', '{"_note": ["RETAINED BUT NOT IN FORCE, via status rather than an inverted date range:", "this rule was published, then paused one day before it took effect, and", "never governed a single claim. ruleInForce() refuses any non-active status.", "It is kept because FSSA said a new policy is coming later in 2026 and this", "is the shape it was heading toward; keeping it makes the history legible", "rather than silently dropping a real published rule. Do not activate it", "without re-reading the then-current bulletin."], "data": {"authority": {"citation": "IHCP Bulletin BT2025173 (December 4, 2025) — superseded by BT2025190 before taking effect", "quote": "Beginning for DOS on or after Jan. 1, 2026, assisted living providers are required to bill for HCBS waiver services using the monthly billing code T2031 U7 UA and either U1, U2 or U3 modifier, when a resident is present in the facility 28 days or more per month. ... If an assisted living provider submits a claim using the daily rate billing code for a member who was present in the facility for more than 27 days, the managed care entity (MCE) or state''s fee-for-service (FFS) contractor will deny the claim.", "read_on": "2026-08-22", "url": "https://www.in.gov/medicaid/providers/files/bulletins/BT2025173.pdf"}, "claim_form": "CMS-1500 / 837P", "code": "T2031", "constraints": ["Under this (paused) policy, billing daily for a resident present 28+ days is denied, and billing monthly for a resident present under 28 days is denied."], "daily": {"code": "T2031", "max_days": 27, "modifiers": ["U7", "<TIER>"], "unit": "1 day"}, "label": "Indiana HCBS Assisted Living (BT2025173 mandate — never took effect, paused by BT2025190)", "monthly": {"code": "T2031", "modifiers": ["U7", "UA", "<TIER>"], "required_at_days": 28, "unit": "1 month"}, "tier_assigned_by": "The waiver service authorization (NOA / Service Authorization form)", "tier_modifiers": {"tier1": "U1", "tier2": "U2", "tier3": "U3"}}, "effective_from": "2026-01-01", "effective_to": null, "program": "medicaid_hcbs", "state": "IN", "status": "never_in_force"}'::jsonb),
  ('IN-HCBS-AL-2026-PAUSED', 'sairncare_payer_rules_seed.json', '{"data": {"authority": {"citation": "IHCP Bulletin BT2025190 (December 31, 2025)", "quote": "the FSSA is pausing the implementation of monthly billing requirements and daily per diem requirements outlined in BT2025173. Until further notice, assisted living providers can continue to bill for Assisted Living waiver services using either the monthly or daily billing method. ... Assisted living providers can bill monthly or daily for services up to 29 days. Monthly billing can still be done even when a resident is out of the facility, as long as the resident is present in the facility for a minimum of 15 days per month. ... Claims for monthly billing can be submitted after the member has been present in the facility for a minimum of 15 days of the month.", "read_on": "2026-08-22", "url": "https://www.in.gov/medicaid/providers/files/bulletins/BT2025190.pdf"}, "claim_form": "CMS-1500 / 837P", "code": "T2031", "constraints": ["Room and board is not covered under either the per-diem or the monthly rate.", "Claims may be submitted only after the HCBS waiver services are rendered; daily claims submitted for future dates of service are denied.", "Documentation is required for each day the member is present in the facility, under either billing method.", "Separate payment is not allowed for Adult Day Services, Adult Family Care, Attendant Care, Home Modifications, Home-Delivered Meals, Home and Community Assistance, Personal Emergency Response System, Pest Control, Respite Care, Structured Family, or Transportation — all are integral to the Assisted Living service.", "This policy is explicitly interim: FSSA stated it will implement a new billing policy later in 2026."], "daily": {"code": "T2031", "max_days": 29, "modifiers": ["U7", "<TIER>"], "unit": "1 day"}, "label": "Indiana HCBS Assisted Living (current policy — mandate paused)", "monthly": {"code": "T2031", "min_days_present": 15, "modifiers": ["U7", "UA", "<TIER>"], "submit_after_days_present": 15, "unit": "1 month"}, "tier_assigned_by": "The waiver service authorization (NOA / Service Authorization form)", "tier_modifiers": {"tier1": "U1", "tier2": "U2", "tier3": "U3"}}, "effective_from": "2025-12-31", "effective_to": null, "program": "medicaid_hcbs", "state": "IN", "status": "active"}'::jsonb),
  ('MI-HCBS-CLS-2026', 'sairncare_payer_rules_seed.json', '{"data": {"_why_this_is_not_a_t2031_state": "Ohio and Indiana both pay assisted living as a per-resident amount under T2031 keyed to days present. Michigan has no equivalent: there is no assisted-living per-diem code in MI Choice at all. The residential setting is where the service happens, not what is billed. Seeding a T2031-shaped rule for Michigan would have been the single most damaging thing available here, because it would have looked exactly like the other two states and produced claims for a code Michigan does not use.", "authority": {"citation": "MDHHS Medicaid Provider Manual — Electronic Visit Verification chapter, § 3.1 PCS Service Codes (change made 4/1/2026), version dated July 1, 2026; and MI Choice Waiver chapter § 4.1 (Covered Waiver Services) and § 8.2 (Encounter Data Reporting), per MSA 21-48 effective January 1, 2022", "quote": "SECTION 3 — PERSONAL CARE SERVICES. 3.1 PCS SERVICE CODES [CHANGE MADE 4/1/2026] ... Program / Procedure Code / Service Description ... MI Choice — H2015 Comprehensive Community Support Services, per 15 minutes; S5150 Unskilled Respite Care, not Hospice, per 15 minutes. ... MI Choice Waiver chapter: CLS provided in a residential setting like assisted living, Adult Foster Care, or Homes for the Aged, includes only those services and supports that are in addition to, and must not replace, usual and customary supports and services furnished to residents in the licensed setting. CLS does not include the costs associated with room and board. ... HCPCS codes S5101 and S5102 are limited to one unit per day. ... Each waiver agency must submit all encounter data to MDHHS within 180 calendar days of the date that services were rendered.", "read_on": "2026-08-23", "url": "https://www.mdch.state.mi.us/dch-medicaid/manuals/MedicaidProviderManual.pdf"}, "billing_model": "reference_only", "codes": [{"code": "H2015", "description": "Comprehensive Community Support Services, per 15 minutes — the MI Choice code for Community Living Supports (CLS)", "evv_required": true, "unit": "15 minutes"}, {"code": "S5150", "description": "Unskilled Respite Care, not Hospice, per 15 minutes — MI Choice", "evv_required": true, "unit": "15 minutes"}, {"code": "S5101", "description": "Adult day health — limited to one unit per day", "limit": "one unit per day", "unit": "1 unit/day"}, {"code": "S5102", "description": "Adult day health — limited to one unit per day", "limit": "one unit per day", "unit": "1 unit/day"}], "constraints": ["CLS provided in a residential setting like assisted living, Adult Foster Care, or a Home for the Aged includes ONLY those services and supports that are IN ADDITION TO, and must not replace, the usual and customary supports and services furnished to residents in the licensed setting. Billing CLS for care the facility''s own licence already obliges it to provide is a duplicate claim.", "CLS does not include the costs associated with room and board.", "Documentation in the participant''s record must clearly identify the need for additional supports not covered by licensure, and the person-centred service plan (PCSP) must clearly identify which portion of the supports is covered by CLS.", "Homemaking tasks incidental to ADL assistance may be included, but must not replace usual and customary homemaking required by licensure.", "CLS excludes nursing and skilled therapy services.", "Where transportation incidental to CLS is included, the waiver agency must not also authorise transportation as a separate waiver service.", "H2015 and S5150 require Electronic Visit Verification for any personal care service starting or ending in the beneficiary''s home.", "Waiver agencies must submit all encounter data to MDHHS within 180 calendar days of the date the services were rendered."], "label": "Michigan MI Choice waiver — Community Living Supports in a licensed residential setting (reference only, not routable)", "modifiers": {"SC": "Waiver agencies must use the SC modifier when billing for ancillary items."}, "not_routable_reason": "MI Choice pays Community Living Supports in 15-MINUTE units of service actually delivered, and the provider bills the WAIVER AGENCY, which then submits encounter data to MDHHS through CHAMPS — the provider does not bill the state directly. Neither the unit count nor the payer can be derived from how many days a resident was present, so this app records the codes and refuses to assemble a claim line. Building one from occupancy would fabricate the unit count on a Medicaid claim.", "tier_model": "none", "unverified": ["Rates. Michigan does not publish a statewide MI Choice fee schedule the way Ohio publishes appendix A or Pennsylvania publishes the OLTL schedule; MI Choice rates are set between MDHHS and each waiver agency. No rate is recorded here.", "Whether any waiver agency requires additional local modifiers beyond SC. The Provider Manual names only SC for ancillary items; agency-level requirements were not surveyed and are not represented."]}, "effective_from": "2026-04-01", "effective_to": null, "program": "medicaid_hcbs", "state": "MI", "status": "active"}'::jsonb),
  ('OH-HCBS-AL-2024', 'sairncare_payer_rules_seed.json', '{"data": {"additional_services": [{"code": "T2038", "cumulative_max": null, "modifiers": ["U4"], "name": "Community transition service", "rate_basis": "Per-job bid rate negotiated and approved by ODA''s designee and accepted by the individual — there is no flat rate. A cumulative maximum is published in appendix A to OAC 5160-1-06.5.", "unit": "1 completed job order"}], "authority": {"citation": "OAC 5160-33-07 (eff. July 1, 2019); OAC 5160-1-06.5 (eff. July 1, 2024); OAC 173-39-02.16 (eff. July 1, 2024); Molina Healthcare of Ohio Nursing Facility and Assisted Living Provider Guide (code/modifier table)", "quote": "A unit rate shall be based on a three-tiered model, and shall not exceed the amounts in appendix A to rule 5160-1-06.5 of the Administrative Code. ... The rate for assisted living services for each individual shall be determined by the ODA''s designee through an assessment of the individual''s service needs in four areas: (a) Cognitive impairments, (b) Medication administration, (c) Nursing services, and (d) Functional impairments.", "read_on": "2026-08-22", "url": "https://codes.ohio.gov/ohio-administrative-code/rule-5160-33-07"}, "claim_form": "CMS-1500", "code": "T2031", "constraints": ["Room and board is not covered by the waiver.", "Bed hold days are not billable for assisted living waiver members.", "Assisted living payment constitutes payment in full: the provider may not bill the individual for any difference between the Medicaid payment and the provider''s charge, or request a co-payment or similar charge.", "Only services authorized by ODA''s designee and reflected on the individual''s person-centered service plan are payable.", "The tier is a per-RESIDENT acuity determination made by ODA''s designee. It is NOT the facility''s certification track (basic service vs memory care) and NOT the critical-access rate qualification — those are separate provider-level attributes that do not determine this modifier."], "daily": {"code": "T2031", "modifiers": ["<TIER>"], "unit": "1 day"}, "label": "Ohio Assisted Living HCBS Waiver", "tier_assigned_by": "The Ohio Department of Aging''s designee, via an assessment of the individual''s service needs in four areas: cognitive impairments, medication administration, nursing services, and functional impairments", "tier_modifiers": {"tier1": "U1", "tier2": "U2", "tier3": "U3"}, "unverified": ["Tier display names. The three tiers are referred to only as Tier 1 / Tier 2 / Tier 3 in the sources reachable for this build; no primary source mapping U1/U2/U3 to specific names was located. Appendix A to OAC 5160-1-06.5 lists rates for ''the basic service'', ''memory care'', and ''critical access rates'' (per OAC 173-39-02.16(E)(1)), but critical access is a qualification available to BOTH basic and memory care providers, so it is not a third parallel tier and that list does not map cleanly onto U1/U2/U3.", "All dollar rates. Appendix A could not be retrieved from a primary source."]}, "effective_from": "2024-07-01", "effective_to": null, "program": "medicaid_hcbs", "state": "OH", "status": "active"}'::jsonb),
  ('PA-HCBS-RESHAB-OBRA-2025', 'sairncare_payer_rules_seed.json', '{"data": {"_the_finding_that_matters_most": "PENNSYLVANIA HAS NO MEDICAID ASSISTED-LIVING PER-DIEM CODE. The OLTL fee schedule effective 2025-01-01 was read line by line and contains no assisted living line item of any kind. The only state-published code that reaches a licensed personal care home or assisted living residence is Residential Habilitation, and its own waiver caps the licensed setting at 8 unrelated individuals — which excludes essentially every facility this app is built for. A rule that simply listed W0102 as ''Pennsylvania''s assisted living code'' would have been sourced, precise, and badly wrong in practice.", "authority": {"citation": "OLTL Home and Community Based Waiver Services Rates, effective January 1, 2025 (procedure codes and units); PA OBRA Waiver Appendix C-3 Waiver Services Specifications, Residential Habilitation service definition; PA DHS OBRA Waiver eligibility criteria", "quote": "OLTL fee schedule: Residential Habilitation 1-3 — W0100 — 1 Day; Residential Habilitation 1-3 Support 1:1 — W0101 U4 — 1 Hour; Residential Habilitation 1-3 Support 2:1 — W0101 U5 — 1 Hour; Residential Habilitation 4-8 — W0102 — 1 Day; Residential Habilitation 4-8 Support 1:1 — W0103 U4 — 1 Hour; Residential Habilitation 4-8 Support 2:1 — W0103 U5 — 1 Hour. ... Appendix C-3: Licensed Settings are settings in which four or more individuals reside and are licensed as Personal Care Homes (reference 55 PA Code Chapter 2600) or Assisted Living Residences (reference 55 PA Code Chapter 2800). ... A day is defined as a period of a minimum of 8 hours of service rendered by a residential habilitation provider within a 24-hour period beginning at 12:00 am and ending at 11:59 pm. ... Effective July 1, 2014 licensed settings serving individuals enrolled in the OBRA Waiver may not exceed a licensed capacity of more than 8 unrelated individuals. ... Payment is not made for room and board.", "read_on": "2026-08-23", "url": "https://www.pa.gov/content/dam/copapwp-pagov/en/dhs/documents/providers/documents/long_term_care_providers/oltl-hcbs-rates-jan-1-2025.pdf"}, "billing_model": "reference_only", "codes": [{"code": "W0100", "description": "Residential Habilitation 1-3 (unlicensed provider-owned setting, no more than three residents)", "unit": "1 day"}, {"code": "W0102", "description": "Residential Habilitation 4-8 (licensed setting: Personal Care Home under 55 Pa. Code Ch. 2600, or Assisted Living Residence under Ch. 2800)", "unit": "1 day"}, {"code": "W0101", "description": "Residential Enhanced Staffing add-on for the 1-3 setting", "modifiers_by_level": {"level_1_1to1": "U4", "level_2_2to1_or_greater": "U5"}, "unit": "1 hour"}, {"code": "W0103", "description": "Residential Enhanced Staffing add-on for the 4-8 setting", "modifiers_by_level": {"level_1_1to1": "U4", "level_2_2to1_or_greater": "U5"}, "unit": "1 hour"}], "community_healthchoices_note": "Community HealthChoices (CHC) is where most Medicaid-funded Pennsylvania assisted living and personal care home residents actually are. CHC is capitated managed care administered through MCOs, so there is no state-published CHC fee schedule to seed: codes and rates for a CHC participant come from the facility''s contract with its MCO. That is a real absence of a state rule, not a gap in this research, and it is why no CHC rule appears here.", "constraints": ["Payment is not made for room and board.", "Effective July 1, 2014, licensed settings serving individuals enrolled in the OBRA Waiver may not exceed a licensed capacity of more than 8 unrelated individuals. A PCH or ALR licensed for 9 or more cannot deliver this service to an OBRA participant at all.", "Licensed settings are settings in which four or more individuals reside and are licensed as Personal Care Homes (55 Pa. Code Ch. 2600) or Assisted Living Residences (55 Pa. Code Ch. 2800). Unlicensed settings have no more than three residents.", "Transportation is a component of the Residential Habilitation rate and may NOT also be billed as a separate transportation service on the individual''s ISP.", "Residential Enhanced Staffing is an hourly ADD-ON, available only where the needs assessment identifies a requirement for continual assistance for medical or behavioural stability. It is not a base rate.", "Residential Habilitation cannot be billed simultaneously with Community Integration, Structured Day Habilitation, Adult Daily Living, job coaching, employment skills development, or one-to-one therapies.", "OBRA waiver eligibility is age 18-59 with a severe developmental physical disability requiring an ICF/ORC level of care, with substantial functional limitations in three or more major life activities. Someone who turns 60 while enrolled may continue."], "label": "Pennsylvania OBRA waiver / Act 150 — Residential Habilitation in a licensed PCH or ALR (reference only, not routable)", "not_routable_reason": "Two independent reasons, either of which is sufficient. (1) The unit is a DAY DEFINED AS A MINIMUM OF 8 HOURS OF RESIDENTIAL HABILITATION rendered within a calendar day — not a day the resident was present, so days-present is only an upper bound on the unit count and using it would over-bill. (2) The population this code reaches is narrow: it is an OBRA-waiver service, and most Pennsylvania assisted living and personal care home residents on Medicaid are in Community HealthChoices instead, which is capitated managed care with no state fee schedule at all.", "tier_model": "none", "unit_definition": "A day is a period of a minimum of 8 hours of service rendered by a residential habilitation provider within a 24-hour period beginning at 12:00 am and ending at 11:59 pm.", "unverified": ["Whether any individual CHC managed care organisation uses these same W-codes in its provider contracts. MCO contracts are not public and were not surveyed.", "Region assignment. The OLTL schedule prices most services by four regions, but Residential Habilitation is priced identically across all four, so no region field is recorded. If a future schedule differentiates them, this rule must be re-read rather than extrapolated."]}, "effective_from": "2025-01-01", "effective_to": null, "program": "medicaid_hcbs", "state": "PA", "status": "active"}'::jsonb),
  ('US-HOSPICE-MA-CARVEOUT-2025', 'sairncare_payer_rules_seed.json', '{"data": {"authority": {"citation": "CMS MLN Matters MM14219 / CR 14219, ''Editing for Outpatient Services Provided to Hospice Enrollees'' (effective April 1, 2026; implementation April 6, 2026)", "quote": "We created a new edit to automatically compare the outpatient claim''s primary diagnosis codes with the hospice claim''s primary diagnosis codes by doing an exact diagnosis match. This edit will deny hospital inpatient and outpatient claims when there''s a hospice claim for the same Medicare patient within the same covered period with condition code 07 or modifier GW with the same primary diagnosis.", "read_on": "2026-08-22", "url": "https://www.cms.gov/files/document/mm14219-outpatient-services-hospice-patients-new-edit.pdf"}, "constraints": ["When an MA enrollee elects hospice, the hospice benefit is paid by FFS Medicare while the MA plan continues to cover Part A/B/D care unrelated to the terminal diagnosis. This is a per-claim relatedness determination, not a one-time enrollment switch.", "The VBID hospice benefit component ended 2024-12-31 and was not revived; the VBID model as a whole terminated beginning CY2026. The carve-out is the standing model.", "GV applies only when the billing provider is the patient''s designated attending physician and is not employed by or under arrangement with the hospice.", "Effective 2026-04-01 (implementation 2026-04-06), CMS CR 14219 automatically denies hospital inpatient and outpatient claims where a hospice claim exists for the same beneficiary in the same covered period with condition code 07 or modifier GW and an EXACT primary-diagnosis match.", "Relatedness is a clinical determination. This engine requires it to be stated and will not infer it."], "label": "Hospice / Medicare Advantage relatedness routing (carve-out model)", "modifiers": {"institutional_unrelated": "Condition Code 07", "professional_related": "GV", "professional_unrelated": "GW"}}, "effective_from": "2025-01-01", "effective_to": null, "program": "hospice_ma", "state": "US", "status": "active"}'::jsonb)
),
licences as (
  select k.key, encode(digest(k.key,'sha256'),'hex') as h
  from public.license_keys k where k.app_id = 'sairncare'
),
live as (
  select l.key as licence, r.rule_id as rule_id,
         (to_jsonb(r) - 'id' - 'license_hash' - 'app_id' - 'created_at' - 'updated_at' - 'verified_by' - 'rule_id') as compute
  from licences l
  join public.alf_payer_rules r on r.license_hash = l.h
),
-- every (licence, seed rule) PAIR. Joining expected straight to live on
-- rule_id alone cannot see "missing from licence A while present on licence B".
wanted as (
  select l.key as licence, x.rule_id, x.seed_file, x.compute
  from licences l cross join expected x
)
select
  coalesce(w.licence, v.licence)   as licence,
  coalesce(w.rule_id, v.rule_id)   as rule_id,
  w.seed_file,
  case
    when v.rule_id is null then 'MISSING -- seed rule never loaded onto this licence'
    when w.rule_id is null then 'ORPHAN -- live row with no seed; origin unknown'
    else 'STALE -- live content differs from the seed'
  end                              as verdict,
  jsonb_pretty(w.compute)          as seed_compute,
  jsonb_pretty(v.compute)          as live_compute
from wanted w
full outer join live v on v.licence = w.licence and v.rule_id = w.rule_id
where v.rule_id is null or w.rule_id is null
   or v.compute is distinct from w.compute
order by 4, 1, 2;
